const skillCollection=document.querySelector(".skill-collection");window.location.href.includes("resume.html")&&fetch("../index.html").then((e=>{if(!e.ok)throw new Error("Failed to fetch index.html");return e.text()})).then((e=>{const t=(new DOMParser).parseFromString(e,"text/html").querySelector(".skills .details-container");skillCollection?.append(t)})).catch((e=>{}));
